public class ArrayStack<T> implements IGenStack<T>{private final T[]data;private int size;public <U extends T> ArrayStack(U...data){this.data=data;}public <V extends T,U extends V> void push(U value)throws StackFullException{if(size==data.length)throw new StackFullException(size);data[size++]=value;}public T pop()throws StackEmptyException{if(size==0)throw new StackEmptyException("empty");return data[--size];}}
